const COLOR_CLASS: Partial<Record<ProviderId, string>> = {
  codex: "text-logo-codex",
  grok: "text-logo-grok",
  groq: "text-logo-groq",
}

export interface PlatformLogoProps {
  /** 平台 id 或厂商预设 id（deepseek / kimi / …）；未知 id 回落首字母圆标 */
  platform: ProviderId
  /** 默认 16px，与 .pen 中的 C/Logo * 组件一致 */
  size?: number
  className?: string
}

/**
 * 区域版本 id 共用平台的标识（同一产品分国内外两个条目，logo 只有一份）：
 * ZCode 国内版 = ZCode、Qoder CN = Qoder、WorkBuddy AI = WorkBuddy、Trae CN = Trae。
 */
const PLATFORM_ALIASES: Partial<Record<ProviderId, PlatformId>> = {
  "zcode-bigmodel": "zcode",
  "qoder-cn": "qoder",
  "workbuddy-ai": "workbuddy",
  "trae-cn": "trae",
  dsh: "deepseek",
}

export function PlatformLogo({ platform: rawPlatform, size = 16, className }: PlatformLogoProps) {
  const platform = PLATFORM_ALIASES[rawPlatform] ?? rawPlatform

  const imageSrc = IMAGE_SOURCES[platform]
  if (imageSrc) {
    const darkSrc = IMAGE_DARK_SOURCES[platform]
    if (darkSrc) {
      return (
        <span
          role="img"
          aria-label={platform}
          data-logo={platform}
          data-logo-source="official-svg"
          style={{ width: size, height: size }}
          className={cn("relative inline-block shrink-0", className)}
        >
          <img src={imageSrc} alt="" draggable={false} className="size-full object-contain dark:hidden" />
          <img src={darkSrc} alt="" draggable={false} className="hidden size-full object-contain dark:block" />
        </span>
      )
    }
    return (
      <img
        src={imageSrc}
        width={size}
        height={size}
        alt={platform}
        draggable={false}
        data-logo={platform}
        data-logo-source="official-svg"
        className={cn("shrink-0 object-contain", className)}
      />
    )
  }

  // 自定义供应商：六边形 + 代码标识，不对应任何厂商商标。
  if (platform === "custom") {
    return (
      <span
        role="img"
        aria-label="自定义供应商"
        data-logo="custom"
        data-logo-source="generic"
        style={{ width: size, height: size, borderRadius: size * 0.27 }}
        className={cn("relative grid shrink-0 place-items-center bg-jn-primary-soft text-jn-primary-ink", className)}
      >
        <Hexagon aria-hidden style={{ width: size * 0.8, height: size * 0.8 }} className="absolute" />
        <Code aria-hidden style={{ width: size * 0.5, height: size * 0.5 }} />
      </span>
    )
  }

  const shape = SHAPES[platform]
  const k = size / 16

  // 未登记的平台用首字母圆标，明确不冒充任何品牌图形。
  if (!shape) {
    const letter = platform.charAt(0).toUpperCase()
    return (
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        className={cn("shrink-0", className)}
        aria-label={platform}
        role="img"
        data-logo={platform}
        data-logo-source="fallback"
      >
        <circle cx={size / 2} cy={size / 2} r={size / 2} className="fill-surface-3" />
        <text
          x="50%"
          y="54%"
          dominantBaseline="middle"
          textAnchor="middle"
          fontSize={size * 0.5}
          fontWeight="700"
          className="fill-text-secondary"
        >
          {letter}
        </text>
      </svg>
    )
  }

  const renderPath = (
    d: string,
    slot: [number, number, number, number],
    box: [number, number, number, number],
    key: number,
    evenodd?: boolean,
  ) => {
    const [sx, sy, sw, sh] = slot
    const [, , bw, bh] = box
    const scaleX = (sw * k) / bw
    const scaleY = (sh * k) / bh
    return (
      <path
        key={key}
        d={d}
        transform={`translate(${sx * k} ${sy * k}) scale(${scaleX} ${scaleY})`}
        fill="currentColor"
        fillRule={evenodd ? "evenodd" : undefined}
      />
    )
  }

  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      className={cn("shrink-0", COLOR_CLASS[platform], className)}
      aria-label={platform}
      role="img"
      data-logo={platform}
      data-logo-source="official-vector"
    >
      {shape.paths.map((d, i) => renderPath(d, shape.slot, shape.box, i, shape.evenodd))}
    </svg>
  )
}
